def _is_objective_id(value: int) -> bool:
    return 1 <= value <= 30


def _is_wire_int(value: object) -> bool:
    """True for a value the wire may encode as an integer (#629 review).

    `bool` is excluded EXPLICITLY, and that is the whole point: `bool` subclasses
    `int` in Python, so `isinstance(True, int)` is True and a stray flag from
    dynamically-sourced data would encode as a perfectly valid 1 or 0 rather than
    failing. The TypeScript encoders reject the same inputs through
    `Number.isSafeInteger` (a boolean is not a number there), so without this the
    two runtimes disagree about what is encodable -- and the Python side is the
    permissive one, which is the direction that corrupts a frame instead of
    rejecting it.

    Used by BOTH integer encoders. The unsigned one had no type check at all, so
    a non-int also reached the comparisons below and raised TypeError instead of
    the ValueError the callers handle; short-circuiting here fixes that too.
    """
    return isinstance(value, int) and not isinstance(value, bool)


